        "Verified launcher package handed to Android" to arrayOf("Naipasa ng launcher package sa Android", "\uAC80\uC99D\uB41C \uB7F0\uCC98 \uD328\uD0A4\uC9C0\uAC00 \uC548\uB4DC\uB85C\uC774\uB4DC\uB85C \uC804\uB2EC\uB418\uC5C8\uC2B5\uB2C8\uB2E4", "\u691C\u8A3C\u6E08\u307F\u30E9\u30F3\u30C1\u30E3\u30FC\u30D1\u30C3\u30B1\u30FC\u30B8\u304CAndroid\u306B\u6E21\u3055\u308C\u307E\u3057\u305F", "\u5DF2\u5C06\u5DF2\u9A8C\u8BC1\u7684\u542F\u52A8\u5668\u5305\u4EA4\u7ED9 Android", "Paquete del lanzador verificado entregado a Android", "G\u00F3i tr\u00ECnh kh\u1EDFi ch\u1EA1y \u0111\u00E3 x\u00E1c minh \u0111\u01B0\u1EE3c chuy\u1EC3n cho Android", "Paket peluncur terverifikasi diserahkan ke Android", "Pacote do lan\u00E7ador verificado entregue ao Android", "تم تسليم حزمة المشغل التي تم التحقق منها إلى Android"),
        "Verified update offer loaded" to arrayOf("Na-load ang na-verify na alok ng update", "\uAC80\uC99D\uB41C \uC5C5\uB370\uC774\uD2B8 \uC81C\uC548\uC774 \uB85C\uB4DC\uB418\uC5C8\uC2B5\uB2C8\uB2E4", "\u691C\u8A3C\u6E08\u307F\u66F4\u65B0\u30AA\u30D5\u30A1\u30FC\u304C\u8AAD\u307F\u8FBC\u307E\u308C\u307E\u3057\u305F", "\u5DF2\u52A0\u8F7D\u5DF2\u9A8C\u8BC1\u7684\u66F4\u65B0\u63D0\u4F9B", "Oferta de actualizaci\u00F3n verificada cargada", "\u0110\u1EC1 ngh\u1ECB c\u1EADp nh\u1EADt \u0111\u00E3 x\u00E1c minh \u0111\u01B0\u1EE3c t\u1EA3i", "Penawaran pembaruan terverifikasi dimuat", "Oferta de atualiza\u00E7\u00E3o verificada carregada", "تم تحميل عرض التحديث الذي تم التحقق منه"),
        "Verifying add-on" to arrayOf("Tine-verify ang add-on", "\uCD94\uAC00 \uAE30\uB2A5\uC744 \uAC80\uC99D \uC911", "\u30A2\u30C9\u30AA\u30F3\u3092\u691C\u8A3C\u4E2D", "\u6B63\u5728\u9A8C\u8BC1\u63D2\u4EF6", "Verificando complemento", "\u0110ang x\u00E1c minh ti\u1EC7n \u00EDch b\u1ED5 sung", "Memverifikasi tambahan", "Verificando complemento", "التحقق من الوظيفة الإضافية"),
        "Verifying integrity and identity" to arrayOf("Tine-verify ang integridad at pagkakakilanlan", "\uBB34\uACB0\uC131\uACFC \uC2E0\uC6D0\uC744 \uAC80\uC99D \uC911", "\u6574\u5408\u6027\u3068\u8B58\u5225\u3092\u691C\u8A3C\u4E2D", "\u6B63\u5728\u9A8C\u8BC1\u5B8C\u6574\u6027\u548C\u8EAB\u4EFD", "Verificando integridad e identidad", "\u0110ang x\u00E1c minh t\u00EDnh to\u00E0n v\u1EB9n v\u00E0 danh t\u00EDnh", "Memverifikasi integritas dan identitas", "Verificando integridade e identidade", "التحقق من النزاهة والهوية"),
        "Verifying launcher update" to arrayOf("Tine-verify ang update ng launcher", "\uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8\uB97C \uAC80\uC99D \uC911", "\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u66F4\u65B0\u3092\u691C\u8A3C\u4E2D", "\u6B63\u5728\u9A8C\u8BC1\u542F\u52A8\u5668\u66F4\u65B0", "Verificando actualizaci\u00F3n del lanzador", "\u0110ang x\u00E1c minh c\u1EADp nh\u1EADt tr\u00ECnh kh\u1EDFi ch\u1EA1y", "Memverifikasi pembaruan peluncur", "Verificando atualiza\u00E7\u00E3o do lan\u00E7ador", "التحقق من تحديث المشغل"),
        "Verifying original game" to arrayOf("Tine-verify ang orihinal na laro", "\uC6D0\uBCF8 \uAC8C\uC784\uC744 \uAC80\uC99D \uC911", "\u5143\u306E\u30B2\u30FC\u30E0\u3092\u691C\u8A3C\u4E2D", "\u6B63\u5728\u9A8C\u8BC1\u539F\u59CB\u6E38\u620F", "Verificando juego original", "\u0110ang x\u00E1c minh tr\u00F2 ch\u01A1i g\u1ED1c", "Memverifikasi permainan asli", "Verificando jogo original", "التحقق من اللعبة الأصلية"),
        "Verifying package integrity, identity, and signing certificate." to arrayOf("Tine-verify ang integridad ng package, pagkakakilanlan, at sertipiko ng pagpirma.", "\uD328\uD0A4\uC9C0 \uBB34\uACB0\uC131, \uC2E0\uC6D0 \uBC0F \uC11C\uBA85 \uC778\uC99D\uC11C\uB97C \uAC80\uC99D \uC911", "\u30D1\u30C3\u30B1\u30FC\u30B8\u306E\u6574\u5408\u6027\u3001\u8B58\u5225\u3001\u7F72\u540D\u8A3C\u660E\u66F8\u3092\u691C\u8A3C\u4E2D", "\u6B63\u5728\u9A8C\u8BC1\u5305\u7684\u5B8C\u6574\u6027\u3001\u8EAB\u4EFD\u548C\u7B7E\u540D\u8BC1\u4E66\u3002", "Verificando integridad del paquete, identidad y certificado de firma.", "\u0110ang x\u00E1c minh t\u00EDnh to\u00E0n v\u1EB9n g\u00F3i, danh t\u00EDnh v\u00E0 ch\u1EE9ng ch\u1EC9 k\u00FD.", "Memverifikasi integritas paket, identitas, dan sertifikat penandatanganan.", "Verificando integridade do pacote, identidade e certificado de assinatura.", "التحقق من سلامة الحزمة والهوية وشهادة التوقيع."),
        "Verifying signed package" to arrayOf("Tine-verify ang may pirma na package", "\uC11C\uBA85\uB41C \uD328\uD0A4\uC9C0\uB97C \uAC80\uC99D \uC911", "\u7F72\u540D\u6E08\u307F\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u691C\u8A3C\u4E2D", "\u6B63\u5728\u9A8C\u8BC1\u5DF2\u7B7E\u540D\u7684\u5305", "Verificando paquete firmado", "\u0110ang x\u00E1c minh g\u00F3i \u0111\u00E3 k\u00FD", "Memverifikasi paket yang ditandatangani", "Verificando pacote assinado", "التحقق من الحزمة الموقعة"),
        "Verifying the changelog for {0}." to arrayOf("Tine-verify ang changelog para sa {0}.", "{0}\uC758 \uBCC0\uACBD \uB85C\uADF8\uB97C \uAC80\uC99D \uC911", "{0} \u306E\u5909\u66F4\u5C65\u6B74\u3092\u691C\u8A3C\u4E2D", "\u6B63\u5728\u9A8C\u8BC1 {0} \u7684\u66F4\u65B0\u65E5\u5FD7\u3002", "Verificando el registro de cambios de {0}.", "\u0110ang x\u00E1c minh nh\u1EADt k\u00FD thay \u0111\u1ED5i cho {0}.", "Memverifikasi catatan perubahan untuk {0}.", "Verificando o registro de altera\u00E7\u00F5es para {0}.", "التحقق من سجل التغيير لـ {0}."),
        "Verifying this add-on before preparing the exact-package shell." to arrayOf("Tine-verify ang add-on na ito bago ihanda ang eksaktong shell ng package.", "\uC815\uD655\uD55C \uD328\uD0A4\uC9C0 \uC178\uC744 \uC900\uBE44\uD558\uAE30 \uC804\uC5D0 \uC774 \uCD94\uAC00 \uAE30\uB2A5\uC744 \uAC80\uC99D \uC911", "\u6B63\u78BA\u306A\u30D1\u30C3\u30B1\u30FC\u30B8\u30B7\u30A7\u30EB\u3092\u6E96\u5099\u3059\u308B\u524D\u306B\u3001\u3053\u306E\u30A2\u30C9\u30AA\u30F3\u3092\u691C\u8A3C\u4E2D", "\u5728\u51C6\u5907\u7CBE\u786E\u5305\u58F3\u4E4B\u524D\u9A8C\u8BC1\u6B64\u63D2\u4EF6\u3002", "Verificando este complemento antes de preparar la versi\u00F3n exacta del paquete.", "\u0110ang x\u00E1c minh ti\u1EC7n \u00EDch b\u1ED5 sung n\u00E0y tr\u01B0\u1EDBc khi chu\u1EA9n b\u1ECB shell g\u00F3i ch\u00EDnh x\u00E1c.", "Memverifikasi tambahan ini sebelum menyiapkan shell paket-eksak.", "Verificando este complemento antes de preparar o shell do pacote exato.", "التحقق من هذه الوظيفة الإضافية قبل إعداد غلاف الحزمة بالضبط."),
        "Verifying this add-on before preparing the patched game." to arrayOf("Tine-verify ang add-on na ito bago ihanda ang na-patch na laro.", "\uD328\uCE58\uB41C \uAC8C\uC784\uC744 \uC900\uBE44\uD558\uAE30 \uC804\uC5D0 \uC774 \uCD94\uAC00 \uAE30\uB2A5\uC744 \uAC80\uC99D \uC911", "\u30D1\u30C3\u30C1\u9069\u7528\u6E08\u307F\u30B2\u30FC\u30E0\u3092\u6E96\u5099\u3059\u308B\u524D\u306B\u3001\u3053\u306E\u30A2\u30C9\u30AA\u30F3\u3092\u691C\u8A3C\u4E2D", "\u5728\u51C6\u5907\u4FEE\u8865\u6E38\u620F\u4E4B\u524D\u9A8C\u8BC1\u6B64\u63D2\u4EF6\u3002", "Verificando este complemento antes de preparar el juego parcheado.", "\u0110ang x\u00E1c minh ti\u1EC7n \u00EDch b\u1ED5 sung n\u00E0y tr\u01B0\u1EDBc khi chu\u1EA9n b\u1ECB tr\u00F2 ch\u01A1i \u0111\u00E3 v\u00E1.", "Memverifikasi tambahan ini sebelum menyiapkan permainan yang diperbaiki.", "Verificando este complemento antes de preparar o jogo modificado.", "التحقق من هذه الوظيفة الإضافية قبل إعداد اللعبة المصححة."),
        "Version {0} is ready" to arrayOf("Handa na ang Bersyon {0}", "\uBC84\uC804 {0}\uC774 \uC900\uBE44\uB418\uC5C8\uC2B5\uB2C8\uB2E4", "\u30D0\u30FC\u30B8\u30E7\u30F3 {0} \u304C\u6E96\u5099\u5B8C\u4E86", "\u7248\u672C {0} \u5DF2\u51C6\u5907\u597D", "La versi\u00F3n {0} est\u00E1 lista", "Phi\u00EAn b\u1EA3n {0} \u0111\u00E3 s\u1EB5n s\u00E0ng", "Versi {0} siap", "Vers\u00E3o {0} est\u00E1 pronta", "الإصدار {0} جاهز"),
        "Version {0} is ready. Review everything that changed before downloading." to arrayOf("Bersyon {0} ay handa na. Suriin ang lahat ng nagbago bago mag-download.", "\uBC84\uC804 {0}\uC774 \uC900\uBE44\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uB2E4\uC6B4\uB85C\uB4DC\uD558\uAE30 \uC804\uC5D0 \uBCC0\uACBD\uB41C \uBAA8\uB4E0 \uB0B4\uC6A9\uC744 \uAC80\uD1A0\uD558\uC138\uC694.", "\u30D0\u30FC\u30B8\u30E7\u30F3 {0} \u304C\u6E96\u5099\u3067\u304D\u307E\u3057\u305F\u3002\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u524D\u306B\u5909\u66F4\u5185\u5BB9\u3092\u3059\u3079\u3066\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u7248\u672C {0} \u5DF2\u51C6\u5907\u597D\u3002\u5728\u4E0B\u8F7D\u524D\u8BF7\u68C0\u67E5\u6240\u6709\u66F4\u6539\u3002", "Versi\u00F3n {0} est\u00E1 lista. Revisa todo lo que cambi\u00F3 antes de descargar.", "Phi\u00EAn b\u1EA3n {0} \u0111\u00E3 s\u1EB5n s\u00E0ng. Xem l\u1EA1i m\u1ECDi th\u1EE9 \u0111\u00E3 thay \u0111\u1ED5i tr\u01B0\u1EDBc khi t\u1EA3i xu\u1ED1ng.", "Versi {0} siap. Tinjau semua yang berubah sebelum mengunduh.", "Vers\u00E3o {0} est\u00E1 pronta. Revise tudo o que mudou antes de baixar.", "الإصدار {0} جاهز. راجع كل ما تغير قبل التنزيل."),
        "Version {0} is the latest available version." to arrayOf("Bersyon {0} ang pinakabagong bersyon na available.", "\uBC84\uC804 {0}\uC774 \uC0AC\uC6A9 \uAC00\uB2A5\uD55C \uCD5C\uC2E0 \uBC84\uC804\uC785\uB2C8\uB2E4.", "\u30D0\u30FC\u30B8\u30E7\u30F3 {0} \u306F\u5229\u7528\u53EF\u80FD\u306A\u6700\u65B0\u30D0\u30FC\u30B8\u30E7\u30F3\u3067\u3059\u3002", "\u7248\u672C {0} \u662F\u53EF\u7528\u7684\u6700\u65B0\u7248\u672C\u3002", "Versi\u00F3n {0} es la \u00FAltima versi\u00F3n disponible.", "Phi\u00EAn b\u1EA3n {0} l\u00E0 phi\u00EAn b\u1EA3n m\u1EDBi nh\u1EA5t hi\u1EC7n c\u00F3.", "Versi {0} adalah versi terbaru yang tersedia.", "Vers\u00E3o {0} \u00E9 a mais recente dispon\u00EDvel.", "الإصدار {0} هو أحدث إصدار متاح."),
        "Version: {0} (build {1})" to arrayOf("Bersyon: {0} (build {1})", "\uBC84\uC804: {0} (\uBE4C\uB4DC {1})", "\u30D0\u30FC\u30B8\u30E7\u30F3: {0} (\u30D3\u30EB\u30C9 {1})", "\u7248\u672C: {0} (\u6784\u5EFA {1})", "Versi\u00F3n: {0} (compilaci\u00F3n {1})", "Phi\u00EAn b\u1EA3n: {0} (b\u1EA3n d\u1EF1ng {1})", "Versi: {0} (build {1})", "Vers\u00E3o: {0} (compila\u00E7\u00E3o {1})", "الإصدار: {0} (النسخة {1})"),
        "Waiting for Android" to arrayOf("Naghihintay para sa Android", "\uC548\uB4DC\uB85C\uC774\uB4DC\uB97C \uAE30\uB2E4\uB9AC\uB294 \uC911", "Android\u3092\u5F85\u3063\u3066\u3044\u307E\u3059", "\u7B49\u5F85 Android", "Esperando Android", "\u0110ang ch\u1EDD Android", "Menunggu Android", "Aguardando Android", "في انتظار الروبوت"),
        "Waiting its turn" to arrayOf("Naghihintay sa kanyang turn", "\uCC28\uB840\uB97C \uAE30\uB2E4\uB9AC\uB294 \uC911", "\u9806\u756A\u3092\u5F85\u3063\u3066\u3044\u307E\u3059", "\u7B49\u5F85\u8F6E\u5230\u5B83", "Esperando su turno", "\u0110ang ch\u1EDD \u0111\u1EBFn l\u01B0\u1EE3t", "Menunggu giliran", "Aguardando sua vez", "في انتظار دوره"),
        "You can now add it to your Jester Mods library." to arrayOf("Maaari mo na itong idagdag sa iyong Jester Mods library.", "\uC774\uC81C Jester Mods \uB77C\uC774\uBE0C\uB7EC\uB9AC\uC5D0 \uCD94\uAC00\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\u3053\u308C\u3092Jester Mods\u30E9\u30A4\u30D6\u30E9\u30EA\u306B\u8FFD\u52A0\u3067\u304D\u308B\u3088\u3046\u306B\u306A\u308A\u307E\u3057\u305F\u3002", "\u4F60\u73B0\u5728\u53EF\u4EE5\u5C06\u5B83\u6DFB\u52A0\u5230\u4F60\u7684 Jester Mods \u5E93\u4E2D\u3002", "Ahora puedes agregarlo a tu biblioteca de Jester Mods.", "B\u00E2y gi\u1EDD b\u1EA1n c\u00F3 th\u1EC3 th\u00EAm n\u00F3 v\u00E0o th\u01B0 vi\u1EC7n Jester Mods c\u1EE7a m\u00ECnh.", "Anda sekarang dapat menambahkannya ke perpustakaan Jester Mods Anda.", "Agora voc\u00EA pode adicion\u00E1-lo \u00E0 sua biblioteca de Jester Mods.", "يمكنك الآن إضافتها إلى مكتبة Jester Mods الخاصة بك."),
        "You can safely start setup again whenever you're ready." to arrayOf("Maaari mo nang ligtas na simulan ang setup muli kapag handa ka na.", "\uC900\uBE44\uAC00 \uB418\uBA74 \uC5B8\uC81C\uB4E0 \uC548\uC804\uD558\uAC8C \uC124\uC815\uC744 \uB2E4\uC2DC \uC2DC\uC791\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\u6E96\u5099\u304C\u3067\u304D\u305F\u3089\u3001\u3044\u3064\u3067\u3082\u5B89\u5168\u306B\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u3092\u518D\u958B\u3067\u304D\u307E\u3059\u3002", "\u4F60\u53EF\u4EE5\u968F\u65F6\u5B89\u5168\u5730\u91CD\u65B0\u5F00\u59CB\u5B89\u88C5\u3002", "Puedes iniciar la configuraci\u00F3n nuevamente de manera segura cuando est\u00E9s listo.", "B\u1EA1n c\u00F3 th\u1EC3 b\u1EAFt \u0111\u1EA7u c\u00E0i \u0111\u1EB7t l\u1EA1i an to\u00E0n b\u1EA5t c\u1EE9 khi n\u00E0o s\u1EB5n s\u00E0ng.", "Anda dapat dengan aman memulai pengaturan lagi kapan saja Anda siap.", "Voc\u00EA pode reiniciar a configura\u00E7\u00E3o com seguran\u00E7a sempre que estiver pronto.", "يمكنك بدء الإعداد بأمان مرة أخرى عندما تكون مستعدًا."),
        "You're up to date" to arrayOf("Updated ka na", "\uCD5C\uC2E0 \uC0C1\uD0DC\uC785\uB2C8\uB2E4", "\u6700\u65B0\u306E\u72B6\u614B\u3067\u3059", "\u4F60\u5DF2\u662F\u6700\u65B0\u7248\u672C", "Est\u00E1s al d\u00EDa", "B\u1EA1n \u0111\u00E3 c\u1EADp nh\u1EADt", "Anda sudah terbaru", "Voc\u00EA est\u00E1 atualizado", "أنت على اطلاع"),
        "Your complete space to review features, manage compatibility, and launch." to arrayOf("Ang iyong kompletong espasyo upang suriin ang mga tampok, pamahalaan ang compatibility, at ilunsad.", "\uAE30\uB2A5\uC744 \uAC80\uD1A0\uD558\uACE0, \uD638\uD658\uC131\uC744 \uAD00\uB9AC\uD558\uBA70, \uC2E4\uD589\uD560 \uC218 \uC788\uB294 \uC644\uC804\uD55C \uACF5\uAC04\uC785\uB2C8\uB2E4.", "\u6A5F\u80FD\u3092\u78BA\u8A8D\u3057\u3001\u4E92\u63DB\u6027\u3092\u7BA1\u7406\u3057\u3001\u8D77\u52D5\u3059\u308B\u305F\u3081\u306E\u5B8C\u5168\u306A\u30B9\u30DA\u30FC\u30B9\u3067\u3059\u3002", "\u4F60\u7684\u5B8C\u6574\u7A7A\u95F4\uFF0C\u7528\u4E8E\u67E5\u770B\u529F\u80FD\u3001\u7BA1\u7406\u517C\u5BB9\u6027\u548C\u542F\u52A8\u3002", "Tu espacio completo para revisar funciones, gestionar compatibilidad y lanzar.", "Kh\u00F4ng gian \u0111\u1EA7y \u0111\u1EE7 c\u1EE7a b\u1EA1n \u0111\u1EC3 xem t\u00EDnh n\u0103ng, qu\u1EA3n l\u00FD kh\u1EA3 n\u0103ng t\u01B0\u01A1ng th\u00EDch v\u00E0 kh\u1EDFi ch\u1EA1y.", "Ruang lengkap Anda untuk meninjau fitur, mengelola kompatibilitas, dan meluncurkan.", "Seu espa\u00E7o completo para revisar recursos, gerenciar compatibilidade e iniciar.", "مساحتك الكاملة لمراجعة الميزات وإدارة التوافق والتشغيل."),
        "Your launcher access has expired. Unlock the launcher again, then retry." to arrayOf("Nag-expire ang iyong access sa launcher. I-unlock muli ang launcher, pagkatapos subukan muli.", "\uB7F0\uCC98 \uC811\uADFC \uAD8C\uD55C\uC774 \uB9CC\uB8CC\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uB7F0\uCC98\uB97C \uB2E4\uC2DC \uC7A0\uAE08 \uD574\uC81C\uD55C \uD6C4 \uC2DC\uB3C4\uD558\uC138\uC694.", "\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u30A2\u30AF\u30BB\u30B9\u671F\u9650\u304C\u5207\u308C\u3066\u3044\u307E\u3059\u3002\u30E9\u30F3\u30C1\u30E3\u30FC\u3092\u518D\u5EA6\u30A2\u30F3\u30ED\u30C3\u30AF\u3057\u3066\u304B\u3089\u3001\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u4F60\u7684\u542F\u52A8\u5668\u8BBF\u95EE\u6743\u9650\u5DF2\u8FC7\u671F\u3002\u8BF7\u91CD\u65B0\u89E3\u9501\u542F\u52A8\u5668\uFF0C\u7136\u540E\u91CD\u8BD5\u3002", "Tu acceso al lanzador ha expirado. Desbloquea el lanzador nuevamente y luego reintenta.", "Quy\u1EC1n truy c\u1EADp tr\u00ECnh kh\u1EDFi ch\u1EA1y c\u1EE7a b\u1EA1n \u0111\u00E3 h\u1EBFt h\u1EA1n. M\u1EDF kh\u00F3a l\u1EA1i tr\u00ECnh kh\u1EDFi ch\u1EA1y, sau \u0111\u00F3 th\u1EED l\u1EA1i.", "Akses peluncur Anda telah kedaluwarsa. Buka kunci peluncur lagi, lalu coba ulangi.", "Seu acesso ao lan\u00E7ador expirou. Desbloqueie o lan\u00E7ador novamente e tente novamente.", "لقد انتهت صلاحية وصول المشغل الخاص بك. قم بإلغاء قفل المشغل مرة أخرى، ثم أعد المحاولة."),
        "Your move" to arrayOf("Alam mo na ang iyong gagawin", "\uB2F9\uC2E0\uC758 \uCC28\uB840\uC785\uB2C8\uB2E4", "\u3042\u306A\u305F\u306E\u756A\u3067\u3059", "\u8F6E\u5230\u4F60\u4E86", "Tu turno", "L\u01B0\u1EE3t c\u1EE7a b\u1EA1n", "Giliran Anda", "Sua vez", "تحركك"),
        "Your partial download was kept safely, so a future retry can resume faster." to arrayOf("Ang iyong partial na download ay ligtas na nakatabi, kaya ang susunod na retry ay mas mabilis na makakapagpatuloy.", "\uBD80\uBD84\uC801\uC73C\uB85C \uB2E4\uC6B4\uB85C\uB4DC\uB41C \uD30C\uC77C\uC740 \uC548\uC804\uD558\uAC8C \uBCF4\uAD00\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uC774\uD6C4 \uC7AC\uC2DC\uB3C4 \uC2DC \uB354 \uBE60\uB974\uAC8C \uC774\uC5B4\uC11C \uC9C4\uD589\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "\u90E8\u5206\u7684\u306A\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u306F\u5B89\u5168\u306B\u4FDD\u6301\u3055\u308C\u3066\u3044\u308B\u306E\u3067\u3001\u5C06\u6765\u306E\u518D\u8A66\u884C\u3067\u3088\u308A\u65E9\u304F\u518D\u958B\u3067\u304D\u307E\u3059\u3002", "\u4F60\u7684\u90E8\u5206\u4E0B\u8F7D\u5DF2\u5B89\u5168\u4FDD\u5B58\uFF0C\u56E0\u6B64\u5C06\u6765\u91CD\u8BD5\u53EF\u4EE5\u66F4\u5FEB\u7EE7\u7EED\u3002", "Tu descarga parcial se ha mantenido de forma segura, por lo que un reintento futuro puede reanudarse m\u00E1s r\u00E1pido.", "T\u1EA3i xu\u1ED1ng m\u1ED9t ph\u1EA7n c\u1EE7a b\u1EA1n \u0111\u00E3 \u0111\u01B0\u1EE3c gi\u1EEF an to\u00E0n, v\u00EC v\u1EADy l\u1EA7n th\u1EED l\u1EA1i sau c\u00F3 th\u1EC3 ti\u1EBFp t\u1EE5c nhanh h\u01A1n.", "Unduhan parsial Anda disimpan dengan aman, sehingga percobaan di masa depan dapat dilanjutkan lebih cepat.", "Seu download parcial foi mantido com seguran\u00E7a, ent\u00E3o uma tentativa futura pode ser retomada mais rapidamente.", "تم الاحتفاظ بالتنزيل الجزئي الخاص بك بشكل آمن، لذلك يمكن استئناف إعادة المحاولة المستقبلية بشكل أسرع."),
        "belongs to a different game" to arrayOf("ay kabilang sa ibang laro", "\uB2E4\uB978 \uAC8C\uC784\uC5D0 \uC18D\uD569\uB2C8\uB2E4", "\u5225\u306E\u30B2\u30FC\u30E0\u306B\u5C5E\u3057\u3066\u3044\u307E\u3059", "\u5C5E\u4E8E\u4E0D\u540C\u7684\u6E38\u620F", "pertenece a un juego diferente", "thu\u1ED9c v\u1EC1 m\u1ED9t tr\u00F2 ch\u01A1i kh\u00E1c", "milik game yang berbeda", "pertence a um jogo diferente", "ينتمي إلى لعبة مختلفة"),
        "belongs to a different launcher" to arrayOf("ay kabilang sa ibang launcher", "\uB2E4\uB978 \uB7F0\uCC98\uC5D0 \uC18D\uD569\uB2C8\uB2E4", "\u5225\u306E\u30E9\u30F3\u30C1\u30E3\u30FC\u306B\u5C5E\u3057\u3066\u3044\u307E\u3059", "\u5C5E\u4E8E\u4E0D\u540C\u7684\u542F\u52A8\u5668", "pertenece a un lanzador diferente", "thu\u1ED9c v\u1EC1 m\u1ED9t tr\u00ECnh kh\u1EDFi ch\u1EA1y kh\u00E1c", "milik peluncur yang berbeda", "pertence a um lan\u00E7ador diferente", "ينتمي إلى قاذفة مختلفة"),
    )
}
